const escape=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const wrap=(title,desc,body)=>`<section class="visual-lab"><div class="lab-heading"><span class="lab-kicker">TRY IT YOURSELF</span><h2>${title}</h2><p>${desc}</p></div>${body}<p class="lab-caption">Illustrative study experiment · values are for learning, not a trained model prediction.</p></section>`;
const range=(id,name,value,min,max,step=1)=>`<label class="lab-control">${name}<output id="${id}Val">${value}</output><input type="range" id="${id}" value="${value}" min="${min}" max="${max}" step="${step}"></label>`;
export function renderLab(l){if(l.id==='s13')return wrap('Watch a filter move.','Change the kernel, stride and padding. See how each choice changes the feature map.',`<div class="lab-columns"><div><div class="pixel-grid" id="convGrid"></div><div class="lab-controls">${range('kernel','Kernel',3,1,5,2)}${range('stride','Stride',1,1,3)}${range('padding','Padding',0,0,2)}</div></div><div class="lab-result"><span>OUTPUT WIDTH</span><strong id="convOutput">5</strong><p id="convFormula"></p><button class="btn secondary small" id="convStep">Move the filter →</button></div></div>`);
if(l.id==='s15'||l.id==='s16')return wrap('What gets the attention?','Change the relevance scores. Softmax turns those scores into weights that always sum to 1.',`<div class="attention-sentence">The <b>robot</b> picked up the <b>cup</b> because <b>it</b> was nearby.</div><div class="lab-columns"><div class="lab-controls">${range('scoreA','robot · relevance score',1,-2,4,.1)}${range('scoreB','cup · relevance score',2,-2,4,.1)}${range('scoreC','nearby · relevance score',0,-2,4,.1)}</div><div class="attention-weights" id="attentionOutput"></div></div><div class="lab-equation" id="attentionFormula"></div>`);
if(l.module===2)return wrap('Two metrics. Different questions.','Adjust the confusion matrix. Precision asks how many positive predictions were right; recall asks how many actual positives were found.',`<div class="lab-columns"><div class="matrix-controls">${range('tp','True positives',40,0,100)}${range('fp','False positives',10,0,100)}${range('fn','False negatives',20,0,100)}${range('tn','True negatives',30,0,100)}</div><div class="metric-results" id="metricOutput"></div></div>`);
if(['s11','s12','s19'].includes(l.id))return wrap('Take a learning step.','Minimize the toy loss L = (w − 3)². Change the learning rate to see small steps, quick progress or overshooting.',`<div class="lab-columns"><div>${range('learningRate','Learning rate',.1,.01,1.1,.01)}<div class="actions mt"><button class="btn" id="trainStep">One gradient step →</button><button class="btn secondary" id="trainReset">Reset</button></div><p class="lab-equation" id="trainFormula"></p></div><div class="lab-result"><span>CURRENT LOSS</span><strong id="trainLoss">9.00</strong><svg viewBox="0 0 300 140" class="train-chart" id="trainChart" aria-label="Loss trajectory"></svg></div></div>`);
if(l.module===5)return wrap('Same task. Four prompt styles.','Switch the method and notice what changes: examples, worked solutions or the instruction itself.',`<div class="lab-tabs" role="tablist">${['Zero-shot','Few-shot','Few-shot-CoT','Zero-shot-CoT'].map((v,i)=>`<button role="tab" aria-selected="${i===0}" data-prompt="${i}" class="${i===0?'selected':''}">${v}</button>`).join('')}</div><pre class="prompt-preview" id="promptPreview"></pre><p class="lab-equation" id="promptRule"></p>`);
return wrap('Connect the idea to the task.','Choose a concept. Uncover its role, then connect it to an example from this lesson.',`<div class="concept-orbit">${l.concepts.map((c,i)=>`<button class="orbit-node ${i===0?'selected':''}" data-concept="${i}">${escape(c.term)}</button>`).join('')}</div><div class="concept-insight" id="conceptInsight"><span class="lab-kicker">01 / ${String(l.concepts.length).padStart(2,'0')}</span><h3>${escape(l.concepts[0].term)}</h3><p>${escape(l.concepts[0].explanation)}</p></div><div class="example"><span class="eyebrow">CONNECT IT TO AN EXAMPLE</span><p>${escape(l.example)}</p></div>`)}
export function bindLab(l,root=document){const find=id=>root.querySelector('#'+id),all=q=>[...root.querySelectorAll(q)];function observe(ids,draw){ids.forEach(id=>find(id)?.addEventListener('input',()=>{const o=find(id+'Val');if(o)o.textContent=find(id).value;draw()}));draw()}
if(find('convGrid')){let pos=0;const draw=()=>{const k=+find('kernel').value,s=+find('stride').value,p=+find('padding').value,n=Math.floor((7+2*p-k)/s)+1;find('convOutput').textContent=n;find('convFormula').textContent=`floor((7 + 2×${p} − ${k}) / ${s}) + 1 = ${n}`;const x=(pos%n)*s-p,y=Math.floor(pos/n)%n*s-p;find('convGrid').innerHTML=Array.from({length:49},(_,i)=>`<span class="pixel ${i%7>=x&&i%7<x+k&&Math.floor(i/7)>=y&&Math.floor(i/7)<y+k?'lit':''}">${(i*7+3)%9}</span>`).join('')};observe(['kernel','stride','padding'],()=>{pos=0;draw()});find('convStep').onclick=()=>{pos++;draw()}}
if(find('attentionOutput'))observe(['scoreA','scoreB','scoreC'],()=>{const scores=['scoreA','scoreB','scoreC'].map(id=>+find(id).value),e=scores.map(Math.exp),sum=e.reduce((a,b)=>a+b),weights=e.map(x=>x/sum);find('attentionOutput').innerHTML=weights.map((w,i)=>`<div><span>${['robot','cup','nearby'][i]}</span><div class="attention-bar"><i style="width:${w*100}%"></i></div><strong>${(w*100).toFixed(1)}%</strong></div>`).join('');find('attentionFormula').textContent=`Softmax weights: ${weights.map(w=>w.toFixed(3)).join(' + ')} ≈ 1.000. Weighted values contribute proportionally.`});
if(find('metricOutput'))observe(['tp','fp','fn','tn'],()=>{const [tp,fp,fn,tn]=['tp','fp','fn','tn'].map(id=>+find(id).value),pct=(a,b)=>b?(100*a/b).toFixed(1)+'%':'Undefined';find('metricOutput').innerHTML=[['Precision',pct(tp,tp+fp),'TP / (TP + FP)'],['Recall',pct(tp,tp+fn),'TP / (TP + FN)'],['Accuracy',pct(tp+tn,tp+fp+fn+tn),'(TP + TN) / all examples']].map(([t,v,f])=>`<div><span>${t}</span><strong>${v}</strong><small>${f}</small></div>`).join('')});
if(find('trainStep')){let w=0,history=[9];const draw=()=>{const loss=(w-3)**2;find('trainLoss').textContent=loss<1e8?loss.toFixed(3):loss.toExponential(2);const max=Math.max(9,...history);find('trainChart').innerHTML=`<path d="M10 5V125H290" fill="none" stroke="currentColor" opacity=".2"/><polyline fill="none" stroke="#245749" stroke-width="3" points="${history.slice(-30).map((v,i,a)=>`${10+i*280/Math.max(1,a.length-1)},${125-v/max*115}`).join(' ')}"/>`;find('trainFormula').textContent=`w = ${w.toFixed(3)} · gradient = 2(w − 3) = ${(2*(w-3)).toFixed(3)} · steps: ${history.length-1}`};observe(['learningRate'],draw);find('trainStep').onclick=()=>{w-=+find('learningRate').value*2*(w-3);history.push((w-3)**2);draw()};find('trainReset').onclick=()=>{w=0;history=[9];draw()}}
if(find('promptPreview')){const prompts=['Solve: There are 4 boxes with 3 pencils in each. How many pencils are there? Return the answer.','Example: 2 boxes × 3 pencils → 6 pencils.\nExample: 3 boxes × 2 pencils → 6 pencils.\nNow solve: 4 boxes × 3 pencils → ?','Worked example: 2 boxes, 3 pencils each. Multiply the number of boxes by pencils per box: 2 × 3 = 6.\nNow solve: 4 boxes with 3 pencils each.','Solve: There are 4 boxes with 3 pencils in each. How many pencils are there? Work through the calculation step by step.'],rules=['No demonstrations. A task instruction only.','Input–output demonstrations, without worked intermediate steps.','A demonstration includes intermediate solution steps.','Stepwise-solving instruction, without demonstrations.'];const show=i=>{find('promptPreview').textContent=prompts[i];find('promptRule').textContent=rules[i];all('[data-prompt]').forEach(b=>{b.classList.toggle('selected',+b.dataset.prompt===i);b.setAttribute('aria-selected',String(+b.dataset.prompt===i))})};all('[data-prompt]').forEach(b=>b.onclick=()=>show(+b.dataset.prompt));show(0)}
all('[data-concept]').forEach(b=>b.onclick=()=>{const i=+b.dataset.concept,c=l.concepts[i],host=find('conceptInsight');all('[data-concept]').forEach(x=>x.classList.toggle('selected',x===b));host.innerHTML='';const n=root.createElement?root:document;const kicker=n.createElement('span');kicker.className='lab-kicker';kicker.textContent=String(i+1).padStart(2,'0')+' / '+l.concepts.length;const h=n.createElement('h3');h.textContent=c.term;const p=n.createElement('p');p.textContent=c.explanation;host.append(kicker,h,p)})}
